import * as actionTypes from './actionTypes'
import axios from 'axios'

export const authStart=()=>{
    return{
        type:actionTypes.AUTH_START
    }
}

export const authSuccess=(token,username)=>{
    console.log(`authSuccess ${username}`)
    return{
        type:actionTypes.AUTH_SUCCESS,
        token:token,
        username:username
    }
}

export const authFail=(error)=>{
    return{
        type:actionTypes.AUTH_FAIL,
        error:error
    }
}


export const authReset=()=>{
    return{
        type:actionTypes.RESET_AUTH_STATE
    }
}

export const logout=()=>{
    localStorage.removeItem('token');
    localStorage.removeItem('expirationDate');
    localStorage.removeItem('username');
    return{
        type:actionTypes.AUTH_LOGOUT,
    }
}

export const checkAuthTimeout = expirationTime =>{
    return dispatch =>{
        setTimeout(()=>{
            dispatch(logout())
        },
        expirationTime * 1000)
    }
}

export const authLogin =(username,password)=>{
    return dispatch => {
        dispatch(authStart());
        axios.post('http://127.0.0.1:8000/rest-auth/login/',
            {
                username:username,
                password:password
            }
        ).then(res=>{
            const token = res.data.key;
            const expirationDate = new Date(new Date().getTime() + 3600 *1000);
            localStorage.setItem('token',token);
            localStorage.setItem('expirationDate',expirationDate);
            dispatch(authSuccess(token,username));
            dispatch(checkAuthTimeout(3600));
        }).catch(err =>{
            console.log("err at actions ",err.message)
            dispatch(authFail(err.message))
        });

    }
}

export const authSignup =(username,email,password1,password2,gender,phone_number)=>{
    return dispatch => {
        dispatch(authStart());
        axios.post('http://127.0.0.1:8000/rest-auth/registration/',
            {
                username:username,
                email:email,
                password1:password1,
                password2:password2,
                gender:gender,
                phone_number:phone_number
            }
        ).then(res=>{
            const token = res.data.key;
            const expirationDate = new Date(new Date().getTime() + 3600 *1000);
            localStorage.setItem('token',token);
            localStorage.setItem('expirationDate',expirationDate);
            console.log('reg req',username)
            dispatch(authSuccess(token,username));
            dispatch(checkAuthTimeout(3600));
        }).catch(err =>{
            dispatch(authFail(err.message))
        });

    }
}

export const authCheckState =()=>{
    return dispatch =>{
        const token = localStorage.getItem('token')
        const username = localStorage.getItem('username')
        if(token === undefined){
            dispatch(logout())
        }else{
            const expirationDate =new Date(localStorage.getItem('expirationDate'));
            if(expirationDate <= new Date()){
                dispatch(logout())
            }else{
                dispatch(authSuccess(token,username));
                dispatch(checkAuthTimeout( (expirationDate.getTime() - new Date().getTime())/1000 ));
            }
        }
    }
}